import{_ as t,o as n,c as s,a2 as e}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"8.1 电动机的结构","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-1-dian-dong-ji-de-jie-gou.md","filePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-1-dian-dong-ji-de-jie-gou.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-1-dian-dong-ji-de-jie-gou.md"};function l(o,a,r,d,p,c){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="_8-1-电动机的结构" tabindex="-1">8.1 电动机的结构 <a class="header-anchor" href="#_8-1-电动机的结构" aria-label="Permalink to &quot;8.1 电动机的结构&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>三相异步电动机是工厂里的&quot;动力之王&quot;,电风扇、水泵、机床、电梯……到处是它的身影。这一节先认识它的&quot;身体结构&quot;:定子(固定部分)和转子(转动部分),以及鼠笼式与绕线式的区别。</p><h2 id="一、电动机的两大部分-定子和转子" tabindex="-1">一、电动机的两大部分:定子和转子 <a class="header-anchor" href="#一、电动机的两大部分-定子和转子" aria-label="Permalink to &quot;一、电动机的两大部分:定子和转子&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│  机座(外壳)                  │</span></span>
<span class="line"><span>│  ┌───────────────────────┐  │</span></span>
<span class="line"><span>│  │ 定子(静止)             │  │  ← 定子铁芯 + 定子绕组</span></span>
<span class="line"><span>│  │    ┌─────────────┐    │  │</span></span>
<span class="line"><span>│  │    │ 转子(旋转)   │    │  │  ← 转子铁芯 + 转子绕组</span></span>
<span class="line"><span>│  │    └─────────────┘    │  │</span></span>
<span class="line"><span>│  └───────────────────────┘  │</span></span>
<span class="line"><span>│  端盖 + 轴承(支撑转子)       │</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>构成</th><th>作用</th></tr></thead><tbody><tr><td><strong>定子</strong></td><td>定子铁芯(硅钢片)+ 定子绕组(三相绕组)</td><td>通三相交流电,产生<strong>旋转磁场</strong></td></tr><tr><td><strong>转子</strong></td><td>转子铁芯 + 转子绕组(笼条/绕组)</td><td>在旋转磁场中受力转动,输出机械动力</td></tr><tr><td>机座、端盖、轴承</td><td>外壳、支撑、转动支撑</td><td>保护与支撑</td></tr><tr><td>气隙</td><td>定子与转子之间很小的间隙</td><td>越小磁路越紧,效率越高</td></tr></tbody></table><blockquote><p>💡 名字来由:定子&quot;定&quot;在原地,转子&quot;转&quot;起来。定子产生磁场&quot;带动&quot;转子转。</p></blockquote><h2 id="二、按转子结构分两类" tabindex="-1">二、按转子结构分两类 <a class="header-anchor" href="#二、按转子结构分两类" aria-label="Permalink to &quot;二、按转子结构分两类&quot;">​</a></h2><h3 id="_1-鼠笼式电动机-最常见" tabindex="-1">1. 鼠笼式电动机(最常见) <a class="header-anchor" href="#_1-鼠笼式电动机-最常见" aria-label="Permalink to &quot;1. 鼠笼式电动机(最常见)&quot;">​</a></h3><p>转子绕组像<strong>鼠笼</strong>(笼条短路):</p><ul><li>转子由<strong>硅钢片</strong>叠成铁芯,槽内放<strong>铜(或铝)导条</strong>,两端用短路环连成一体;</li><li>外观就像&quot;鼠笼&quot;,所以叫鼠笼式。</li></ul><p><strong>优点</strong>:结构简单、坚固耐用、价格便宜、维护方便; <strong>缺点</strong>:启动性能一般(启动电流大、启动转矩不大)。</p><h3 id="_2-绕线式电动机" tabindex="-1">2. 绕线式电动机 <a class="header-anchor" href="#_2-绕线式电动机" aria-label="Permalink to &quot;2. 绕线式电动机&quot;">​</a></h3><p>转子有<strong>三相绕组</strong>,通过集电环(滑环)与外部电阻连接:</p><ul><li>可以串接电阻改善启动和调速性能;</li><li>结构复杂、价格高,用于<strong>启动转矩要求高、需要调速</strong>的场合(如起重机)。</li></ul><blockquote><p>💡 记忆:<strong>&quot;鼠笼简单便宜,绕线能调速好启&quot;</strong>。绝大多数普通场合用鼠笼式。</p></blockquote><h2 id="三、定子绕组的三相引出线" tabindex="-1">三、定子绕组的三相引出线 <a class="header-anchor" href="#三、定子绕组的三相引出线" aria-label="Permalink to &quot;三、定子绕组的三相引出线&quot;">​</a></h2><p>定子三相绕组(U 相、V 相、W 相)的六个出线端接在<strong>接线盒</strong>里,标号如下(第 8.3 节接线时要用):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U1、U2      V1、V2      W1、W2</span></span>
<span class="line"><span>(U相首尾)  (V相首尾)  (W相首尾)</span></span></code></pre></div><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 电动机两大组成部分:<strong>定子</strong>(产生旋转磁场)和<strong>转子</strong>(受力转动)。</li><li>✅ <strong>鼠笼式</strong>转子:结构简单、便宜、常用;绕线式:可调速、启转矩大。</li><li>✅ 定子、转子由<strong>硅钢片</strong>叠成,减小涡流损耗。</li><li>⚠️ 易混点:定子通三相电产生磁场(电→磁),转子被磁场带着转(磁→力),两个环节别混。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>三相异步电动机 = 定子(磁场)+ 转子(受力转动)。</li><li>转子分鼠笼式(常用)和绕线式(调速用)。</li><li>定子绕组六个出线端 U1U2、V1V2、W1W2 用于接线。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(判断)三相异步电动机由定子和转子两大部分组成。( )</li><li>(单选)结构简单、价格便宜、应用最广泛的电动机转子是()。 A. 绕线式　B. 鼠笼式　C. 直流式　D. 同步式</li><li>(判断)定子绕组通入三相交流电,会产生旋转磁场。( )</li><li>(单选)定子和转子铁芯用硅钢片叠成,主要是为了()。 A. 减小涡流损耗　B. 减轻重量　C. 便于散热　D. 减小噪音</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。定子 + 转子(加机座、轴承)。</li><li><strong>B</strong>。鼠笼式结构简单、便宜、最常用。</li><li><strong>√</strong>。三相交流电产生旋转磁场。</li><li><strong>A</strong>。硅钢片叠压减小涡流损耗。</li></ol></details>`,26)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
